import type { PersistStorage, StorageValue } from "zustand/middleware";

/**
 * Adapts chrome.storage.local to zustand's PersistStorage interface so
 * stores persist across popup/content-script reloads without touching
 * localStorage (unavailable in the MV3 service worker and isolated content
 * script world in a reliable way).
 */
export function createChromeStoragePersister<T>(): PersistStorage<T> {
  return {
    async getItem(name) {
      const result = await chrome.storage.local.get(name);
      return (result[name] as StorageValue<T> | undefined) ?? null;
    },
    async setItem(name, value) {
      await chrome.storage.local.set({ [name]: value });
    },
    async removeItem(name) {
      await chrome.storage.local.remove(name);
    },
  };
}
