import { create } from "zustand";
import { persist } from "zustand/middleware";
import { createChromeStoragePersister } from "@/shared/services/storage/zustandChromeStorage";
import {
  DEFAULT_THEME,
  PANEL_DEFAULT_SPLIT_PERCENT,
  TEST_PANEL_DEFAULT_HEIGHT_PX,
  type ThemeMode,
} from "@/ui/tokens";

interface WorkspaceState {
  theme: ThemeMode;
  /** Master switch: when false the content script leaves CSES untouched. */
  enabled: boolean;
  sidebarOpen: boolean;
  splitPercent: number;
  testPanelHeightPx: number;
  setTheme: (theme: ThemeMode) => void;
  toggleTheme: () => void;
  setEnabled: (enabled: boolean) => void;
  setSidebarOpen: (open: boolean) => void;
  toggleSidebar: () => void;
  setSplitPercent: (percent: number) => void;
  setTestPanelHeightPx: (height: number) => void;
}

export const useWorkspaceStore = create<WorkspaceState>()(
  persist(
    (set) => ({
      theme: DEFAULT_THEME,
      enabled: true,
      sidebarOpen: true,
      splitPercent: PANEL_DEFAULT_SPLIT_PERCENT,
      testPanelHeightPx: TEST_PANEL_DEFAULT_HEIGHT_PX,
      setTheme: (theme) => set({ theme }),
      toggleTheme: () =>
        set((s) => ({ theme: s.theme === "dark" ? "light" : "dark" })),
      setEnabled: (enabled) => set({ enabled }),
      setSidebarOpen: (sidebarOpen) => set({ sidebarOpen }),
      toggleSidebar: () => set((s) => ({ sidebarOpen: !s.sidebarOpen })),
      setSplitPercent: (splitPercent) => set({ splitPercent }),
      setTestPanelHeightPx: (testPanelHeightPx) => set({ testPanelHeightPx }),
    }),
    {
      name: "leetify:workspace",
      storage: createChromeStoragePersister(),
    }
  )
);

/**
 * chrome.storage reads are async, so the store starts with defaults and
 * patches persisted values in later. Decisions that must respect
 * persisted state before doing anything visible (e.g. "is the extension
 * enabled?") have to await this first.
 */
export function waitForWorkspaceHydration(): Promise<void> {
  if (useWorkspaceStore.persist.hasHydrated()) return Promise.resolve();
  return new Promise((resolve) => {
    const unsub = useWorkspaceStore.persist.onFinishHydration(() => {
      unsub();
      resolve();
    });
  });
}
